pub(crate) struct Reader { pub(crate) chars: Vec<char>, pub(crate) pos: usize, pub(crate) source_mode: bool, pub(crate) unclosed_block_comment: bool }
pub(crate) fn parse_all(s:&str)->Result<Vec<Value>>{
    let trimmed=s.trim();
    let mut r=Reader{chars:s.chars().collect(),pos:0,source_mode:true,unclosed_block_comment:false}; let mut out=Vec::new(); loop {r.skip_ws();if r.unclosed_block_comment{return Err(SchemeError::new("read-error",vec![Value::string("unexpected end of input while reading #|")]))}if r.pos>=r.chars.len(){break} match r.read_expr(){ Ok(v)=>out.push(v), Err(e)=>{ if e.tag=="read-error" && matches!(e.args.get(0), Some(Value::String(msg)) if msg.borrow().as_str()=="unexpected )") { continue; } else { return Err(e); } } } } Ok(out)
}
